// Field guide pages and the hub (generated by scripts/build-field-guides.mjs).
// The contents list is baked into the page; this adds the same prose
// enhancement the writeups get (heading anchors, highlighting, copy-able code
// blocks) and marks the section being read in the contents list.
import { enhanceMarkdownBody } from "../js/markdown.js?v=276fa973-lean";
import { initCommandPalette } from "../js/command-palette.js?v=search2";
import { initSiteHeader } from "../js/site-header.js?v=276fa973-header";
import { initTheme } from "../js/theme.js?v=276fa973";

const trackContents = () => {
  const links = new Map([...document.querySelectorAll(".guide-toc-panel .writeup-toc-link")].map((link) => [link.hash.slice(1), link]));
  if (!links.size || !("IntersectionObserver" in window)) return;
  let active = null;
  const observer = new IntersectionObserver((entries) => {
    const visible = entries.filter((entry) => entry.isIntersecting && links.has(entry.target.id));
    if (!visible.length) return;
    const top = visible.sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
    active?.classList.remove("is-active");
    active = links.get(top.target.id);
    active.classList.add("is-active");
    // keep the marked link in view inside the rail without moving the page
    const panel = active.closest(".guide-toc-panel");
    if (panel && (active.offsetTop < panel.scrollTop || active.offsetTop > panel.scrollTop + panel.clientHeight - 32)) {
      panel.scrollTop = active.offsetTop - panel.clientHeight / 3;
    }
  }, { rootMargin: "0px 0px -70% 0px" });
  links.forEach((_, id) => {
    const heading = document.getElementById(id);
    if (heading) observer.observe(heading);
  });
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  // the contents ship open so they work without scripts; on narrow screens,
  // where they sit above the article, start them folded
  const toc = document.querySelector("[data-guide-toc]");
  if (toc && !window.matchMedia("(min-width: 1100px)").matches) toc.open = false;
  const body = document.querySelector(".markdown-body");
  if (body) {
    enhanceMarkdownBody(body);
    trackContents();
  }
});
